const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry and time periods
  const seattle = ee.Geometry.Point([-122.3321, 47.6062]);
  const buffer = seattle.buffer(10000); // 10km buffer around Seattle

  // 2. Get CHIRPS precipitation data for each year
  const rainfall2019 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate('2019-09-01', '2019-12-01')
    .filterBounds(seattle);

  const rainfall2020 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate('2020-09-01', '2020-12-01')
    .filterBounds(seattle);

  const rainfall2021 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate('2021-09-01', '2021-12-01')
    .filterBounds(seattle);

  // Check collection sizes
  const size2019 = await rainfall2019.size().getInfo();
  const size2020 = await rainfall2020.size().getInfo();
  const size2021 = await rainfall2021.size().getInfo();

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);
  console.log(`2021 Images: ${size2021}`);

  if (size2019 === 0 || size2020 === 0 || size2021 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Sum precipitation for each period
  const sum2019 = rainfall2019.select('precipitation').sum();
  const sum2020 = rainfall2020.select('precipitation').sum();
  const sum2021 = rainfall2021.select('precipitation').sum();

  // 4. Calculate total rainfall with pixel count validation
  const stats2019 = await sum2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: buffer,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2020 = await sum2020.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: buffer,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2021 = await sum2021.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: buffer,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const total2019 = stats2019.precipitation_mean;
  const total2020 = stats2020.precipitation_mean;
  const total2021 = stats2021.precipitation_mean;
  const count2019 = stats2019.precipitation_count;
  const count2020 = stats2020.precipitation_count;
  const count2021 = stats2021.precipitation_count;

  console.log(`2019: ${total2019?.toFixed(2)} mm (Pixels: ${count2019})`);
  console.log(`2020: ${total2020?.toFixed(2)} mm (Pixels: ${count2020})`);
  console.log(`2021: ${total2021?.toFixed(2)} mm (Pixels: ${count2021})`);

  // 5. Validation and final answer
  if (count2019 === 0 || count2020 === 0 || count2021 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (total2019 == null || total2020 == null || total2021 == null || 
      isNaN(total2019) || isNaN(total2020) || isNaN(total2021)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if 2021 rainfall is larger than both 2020 AND 2019
  if (total2021 > total2020 && total2021 > total2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
